-- Hoppo migration 007: translations of the sock products (24 November 2026). Safe to run again.
do $$
declare fam jsonb := $j${"en": "Handmade baby socks", "de": "Handgemachte Babysocken", "es": "Calcetines de bebé hechos a mano", "fr": "Chaussettes de bébé faites main", "hr": "Ručno pletene čarapice za bebe", "it": "Calzini fatti a mano per bebè", "nl": "Handgemaakte babysokjes", "pl": "Ręcznie robione skarpetki dla niemowląt", "pt": "Meias de bebé feitas à mão", "ro": "Șosete tricotate manual pentru bebeluși", "sl": "Ročno pletene nogavice za dojenčke"}$j$::jsonb; dsc jsonb := $j${"en": "Knitted by hand in Slovenia by a grandmother of the Hoppo family.\nOne size for babies from 0 to 12 months.", "de": "Von Hand in Slowenien gestrickt von einer Großmutter der Hoppo-Familie.\nEine Größe für Babys von 0 bis 12 Monaten.", "es": "Tejidos a mano en Eslovenia por una abuela de la familia Hoppo.\nTalla única para bebés de 0 a 12 meses.", "fr": "Tricotées à la main en Slovénie par une grand-mère de la famille Hoppo.\nTaille unique pour les bébés de 0 à 12 mois.", "hr": "Ručno ih je u Sloveniji isplela baka iz obitelji Hoppo.\nJedna veličina za bebe od 0 do 12 mjeseci.", "it": "Lavorati a maglia a mano in Slovenia da una nonna della famiglia Hoppo.\nTaglia unica per bebè da 0 a 12 mesi.", "nl": "Met de hand gebreid in Slovenië door een grootmoeder van de Hoppo-familie.\nEén maat voor baby's van 0 tot 12 maanden.", "pl": "Zrobione ręcznie na drutach w Słowenii przez babcię z rodziny Hoppo.\nJeden rozmiar dla niemowląt w wieku od 0 do 12 miesięcy.", "pt": "Tricotadas à mão na Eslovénia por uma avó da família Hoppo.\nTamanho único para bebés dos 0 aos 12 meses.", "ro": "Tricotate manual în Slovenia de o bunică din familia Hoppo.\nO singură mărime pentru bebeluși de la 0 la 12 luni.", "sl": "V Sloveniji jih ročno plete babica iz družine Hoppo.\nEna velikost za dojenčke od 0 do 12 mesecev."}$j$::jsonb; det jsonb := $j${"en": "Composition: 65% acrylic, 25% wool, 10% viscose.\nLength 9 cm, stretches to 11 cm. Foot height 3 cm. Ankle to top 7 cm.\nPlease measure your baby's foot before you order.\nCare: hand wash at 30 degrees, dry flat.\nSold by Darija Mesko s.p., Vrhnika, Slovenia.", "de": "Zusammensetzung: 65 % Polyacryl, 25 % Wolle, 10 % Viskose.\nLänge 9 cm, dehnbar auf 11 cm. Fußhöhe 3 cm. Knöchel bis Rand 7 cm.\nBitte messen Sie vor der Bestellung den Fuß Ihres Babys.\nPflege: Handwäsche bei 30 Grad, liegend trocknen.\nVerkauf durch Darija Mesko s.p., Vrhnika, Slowenien.", "es": "Composición: 65% acrílico, 25% lana, 10% viscosa.\nLargo 9 cm, se estira hasta 11 cm. Altura del pie 3 cm. Del tobillo al borde superior 7 cm.\nMida el pie de su bebé antes de hacer el pedido.\nCuidado: lavar a mano a 30 grados, secar en plano.\nVendido por Darija Mesko s.p., Vrhnika, Eslovenia.", "fr": "Composition : 65 % acrylique, 25 % laine, 10 % viscose.\nLongueur 9 cm, s'étire jusqu'à 11 cm. Hauteur du pied 3 cm. De la cheville au bord supérieur 7 cm.\nMesurez le pied de votre bébé avant de commander.\nEntretien : lavage à la main à 30 degrés, séchage à plat.\nVendu par Darija Mesko s.p., Vrhnika, Slovénie.", "hr": "Sastav: 65 % akril, 25 % vuna, 10 % viskoza.\nDuljina 9 cm, rasteže se do 11 cm. Visina stopala 3 cm. Od gležnja do vrha 7 cm.\nMolimo izmjerite stopalo svoje bebe prije narudžbe.\nNjega: ručno pranje na 30 stupnjeva, sušiti na ravnoj podlozi.\nProdavatelj: Darija Mesko s.p., Vrhnika, Slovenija.", "it": "Composizione: 65% acrilica, 25% lana, 10% viscosa.\nLunghezza 9 cm, si allunga fino a 11 cm. Altezza del piede 3 cm. Dalla caviglia all'orlo 7 cm.\nMisuri il piede del Suo bebè prima di ordinare.\nCura: lavaggio a mano a 30 gradi, asciugatura in piano.\nVenduto da Darija Mesko s.p., Vrhnika, Slovenia.", "nl": "Samenstelling: 65% acryl, 25% wol, 10% viscose.\nLengte 9 cm, rekt uit tot 11 cm. Voethoogte 3 cm. Enkel tot bovenkant 7 cm.\nMeet de voet van uw baby voordat u bestelt.\nVerzorging: handwassen op 30 graden, plat laten drogen.\nVerkocht door Darija Mesko s.p., Vrhnika, Slovenië.", "pl": "Skład: 65% akryl, 25% wełna, 10% wiskoza.\nDługość 9 cm, rozciąga się do 11 cm. Wysokość stopy 3 cm. Od kostki do góry 7 cm.\nProsimy zmierzyć stopę dziecka przed złożeniem zamówienia.\nPielęgnacja: pranie ręczne w temperaturze 30 stopni, suszyć na płasko.\nSprzedawca: Darija Mesko s.p., Vrhnika, Słowenia.", "pt": "Composição: 65% acrílico, 25% lã, 10% viscose.\nComprimento 9 cm, estica até 11 cm. Altura do pé 3 cm. Do tornozelo ao topo 7 cm.\nMeça o pé do seu bebé antes de encomendar.\nCuidados: lavar à mão a 30 graus, secar na horizontal.\nVendido por Darija Mesko s.p., Vrhnika, Eslovénia.", "ro": "Compoziție: 65% acrilic, 25% lână, 10% viscoză.\nLungime 9 cm, se întinde până la 11 cm. Înălțimea piciorului 3 cm. De la gleznă până sus 7 cm.\nVă rugăm să măsurați piciorul bebelușului înainte de a comanda.\nÎngrijire: spălare de mână la 30 de grade, uscare pe orizontală.\nVândute de Darija Mesko s.p., Vrhnika, Slovenia.", "sl": "Sestava: 65 % akril, 25 % volna, 10 % viskoza.\nDolžina 9 cm, raztegljivo do 11 cm. Višina stopala 3 cm. Od gležnja do vrha 7 cm.\nPred naročilom izmerite stopalo svojega dojenčka.\nNega: ročno pranje pri 30 stopinjah, sušenje na ravni podlagi.\nProdajalec: Darija Mesko s.p., Vrhnika, Slovenija."}$j$::jsonb; cols jsonb := $j${"sunny-yellow": {"en": "Sunny yellow", "de": "Sonnengelb", "es": "Amarillo sol", "fr": "Jaune soleil", "hr": "Sunčano žuta", "it": "Giallo sole", "nl": "Zonnegeel", "pl": "Słoneczny żółty", "pt": "Amarelo sol", "ro": "Galben însorit", "sl": "Sončno rumena"}, "cream-white": {"en": "Cream white", "de": "Cremeweiß", "es": "Blanco crema", "fr": "Blanc crème", "hr": "Krem bijela", "it": "Bianco panna", "nl": "Crèmewit", "pl": "Kremowy", "pt": "Branco creme", "ro": "Alb crem", "sl": "Kremno bela"}, "sky-blue": {"en": "Sky blue", "de": "Himmelblau", "es": "Azul cielo", "fr": "Bleu ciel", "hr": "Nebesko plava", "it": "Azzurro cielo", "nl": "Hemelsblauw", "pl": "Błękitny", "pt": "Azul céu", "ro": "Albastru cer", "sl": "Nebesno modra"}, "rose-pink": {"en": "Rose pink", "de": "Rosa", "es": "Rosa intenso", "fr": "Rose", "hr": "Ružičasta", "it": "Rosa intenso", "nl": "Roze", "pl": "Różowy", "pt": "Rosa forte", "ro": "Roz trandafiriu", "sl": "Rožnata"}, "green-and-white": {"en": "Green and white", "de": "Grün-Weiß", "es": "Verde y blanco", "fr": "Vert et blanc", "hr": "Zelena i bijela", "it": "Verde e bianco", "nl": "Groen met wit", "pl": "Zielony z bielą", "pt": "Verde e branco", "ro": "Verde cu alb", "sl": "Zelena in bela"}, "mint-speckle": {"en": "Mint speckle", "de": "Mintgrün gesprenkelt", "es": "Menta con motas", "fr": "Menthe chinée", "hr": "Prošarana mint", "it": "Menta screziata", "nl": "Mintgroen gespikkeld", "pl": "Miętowy melanż", "pt": "Menta salpicado", "ro": "Verde mentă cu picățele", "sl": "Mentolno zelena, pikasta"}, "lilac-and-white": {"en": "Lilac and white", "de": "Flieder-Weiß", "es": "Lila y blanco", "fr": "Lilas et blanc", "hr": "Lila i bijela", "it": "Lilla e bianco", "nl": "Lila met wit", "pl": "Liliowy z bielą", "pt": "Lilás e branco", "ro": "Liliachiu cu alb", "sl": "Lila in bela"}, "lilac": {"en": "Lilac", "de": "Flieder", "es": "Lila", "fr": "Lilas", "hr": "Lila", "it": "Lilla", "nl": "Lila", "pl": "Liliowy", "pt": "Lilás", "ro": "Liliachiu", "sl": "Lila"}, "apricot-speckle": {"en": "Apricot speckle", "de": "Aprikose gesprenkelt", "es": "Albaricoque con motas", "fr": "Abricot chiné", "hr": "Prošarana marelica", "it": "Albicocca screziata", "nl": "Abrikooskleurig gespikkeld", "pl": "Morelowy melanż", "pt": "Alperce salpicado", "ro": "Caisiu cu picățele", "sl": "Marelična, pikasta"}, "baby-pink": {"en": "Baby pink", "de": "Babyrosa", "es": "Rosa bebé", "fr": "Rose layette", "hr": "Svijetloružičasta", "it": "Rosa baby", "nl": "Babyroze", "pl": "Jasnoróżowy", "pt": "Rosa bebé", "ro": "Roz bebe", "sl": "Svetlo rožnata"}}$j$::jsonb; k text; c jsonb; l text;
begin
  for k, c in select * from jsonb_each(cols) loop
    update public.products set family_name = fam, colour = c, description = dsc, details = det, updated_at = now(),
      name = (select jsonb_object_agg(e.key, fam->>e.key || ', ' || e.value) from jsonb_each_text(c) e) where slug = 'socks-' || k;
  end loop;
end $$;
